.pricing-card { font-family: system-ui, sans-serif; box-sizing: border-box; max-width: 340px; padding: 24px; border-radius: 12px; border: 1px solid #e2e8f0; background: #ffffff; color: #0f172a; }
.badge { display: inline-block; padding: 4px 10px; border-radius: 6px; background: #e0f2fe; color: #0369a1; font-size: 11px; font-weight: 700; text-transform: uppercase; }
.pricing-card h3 { margin: 12px 0 4px; font-size: 18px; }
.price { margin: 0 0 10px; font-size: 28px; font-weight: 800; color: #0f172a; }
.price span { font-size: 14px; font-weight: 500; color: #64748b; }
.desc { margin: 0; font-size: 13px; line-height: 1.5; color: #475569; }

